-- ============================================================================
-- 00087_food_items — what a recipe line IS, per 100 g (exact macros, P1).
-- GENERATED by web/scripts/buildRecipes.mjs. Do not edit; regenerate.
--
-- The ingredient graph says what a line CONTAINS ("Milk" is curd, paneer and
-- cream alike). A food item says what it is, for sizing a portion: per-100 g
-- figures for the raw, edible food. Most rows are IFCT 2017 (ICMR-NIN), with
-- the IFCT food code in source_ref; the rest say where they come from:
-- usda_fdc (USDA FoodData Central), icmr_nvif_1989 (Nutritive Value of Indian
-- Foods), or koi_estimate (a typical label). A KOI shelf line is sized with the
-- product's own label first; a food item is the fallback, and the only source
-- for fresh and kitchen lines. IFCT energy is kJ / 4.184; carbs are available
-- carbohydrate, fibre separate. measures: grams per cup / tbsp / tsp / piece.
-- This is the seed of KOI's food database: rows carry a data_version.
-- ============================================================================

CREATE TABLE IF NOT EXISTS food.food_item (
  key           text PRIMARY KEY CHECK (key ~ '^[a-z0-9_]+$'),
  name          text NOT NULL CHECK (btrim(name) <> ''),
  kcal_100g     numeric(6,1) NOT NULL CHECK (kcal_100g >= 0),
  protein_100g  numeric(6,2) NOT NULL CHECK (protein_100g >= 0),
  carbs_100g    numeric(6,2) NOT NULL CHECK (carbs_100g >= 0),
  fat_100g      numeric(6,2) NOT NULL CHECK (fat_100g >= 0),
  fibre_100g    numeric(6,2) NOT NULL DEFAULT 0 CHECK (fibre_100g >= 0),
  source        text NOT NULL CHECK (source IN ('ifct_2017', 'usda_fdc', 'icmr_nvif_1989', 'koi_estimate')),
  source_ref    text NOT NULL CHECK (btrim(source_ref) <> ''),
  fridge_days   smallint CHECK (fridge_days IS NULL OR fridge_days BETWEEN 0 AND 365),
  cooked_yield  numeric(4,2) CHECK (cooked_yield IS NULL OR cooked_yield > 0),
  measures      jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(measures) = 'object'),
  piece_name    text,
  piece_is_name boolean NOT NULL DEFAULT false,
  data_version  text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE food.food_item IS 'Per-100 g figures (raw, edible) for the foods recipe lines are sized with. IFCT 2017 first; source + source_ref on every row. Seed of the food database.';

ALTER TABLE food.food_item ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON food.food_item FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON food.food_item TO service_role;

ON CONFLICT (key) DO UPDATE SET
  name = EXCLUDED.name, kcal_100g = EXCLUDED.kcal_100g, protein_100g = EXCLUDED.protein_100g,
  carbs_100g = EXCLUDED.carbs_100g, fat_100g = EXCLUDED.fat_100g, fibre_100g = EXCLUDED.fibre_100g,
  source = EXCLUDED.source, source_ref = EXCLUDED.source_ref, fridge_days = EXCLUDED.fridge_days,
  cooked_yield = EXCLUDED.cooked_yield, measures = EXCLUDED.measures, piece_name = EXCLUDED.piece_name,
  piece_is_name = EXCLUDED.piece_is_name, data_version = EXCLUDED.data_version;
